begin;
do $rf101import$
declare
 payload jsonb := $rf101data${"course": {"id": "4c7cbaa4-ceb0-5b42-ae9e-692576e98585", "slug": "rf-101-your-first-day-in-hardware-retail", "version": 1, "title": "Your First Day in Hardware Retail", "description": "Learn how independent hardware stores serve their communities. Build the habits of a dependable teammate. Practice clear communication and helpful customer interactions.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "fa099819-bb26-53cd-83cf-ccd554598e19", "position": 1, "title": "What Makes Independent Hardware Stores Different?", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Local needs shape the value of independent stores. Your work helps build trust."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Lesson introduction"}, {"type": "paragraph", "text": "Every community needs places to buy supplies for homes and businesses."}, {"type": "paragraph", "text": "Hardware stores help meet those needs."}, {"type": "paragraph", "text": "A homeowner may need supplies to repair a fence. A contractor may need materials for a job. A gardener may need soil or fertilizer."}, {"type": "paragraph", "text": "Each customer has a different goal."}, {"type": "paragraph", "text": "Independent hardware stores serve these customers through local knowledge, useful products, and personal service."}, {"type": "heading", "text": "What is an independent hardware store?"}, {"type": "paragraph", "text": "An independent hardware store is owned by an individual, family, or independent company."}, {"type": "paragraph", "text": "Some stores belong to purchasing cooperatives. These groups help stores buy merchandise and access business resources."}, {"type": "paragraph", "text": "Independent stores often make their own decisions about products and services."}, {"type": "paragraph", "text": "These decisions can reflect local needs."}, {"type": "bullet", "text": "A coastal store may carry extra storm supplies and rust-resistant hardware."}, {"type": "bullet", "text": "A rural store may stock fencing, irrigation supplies, and farm equipment parts."}, {"type": "bullet", "text": "A downtown store may offer specialty products for repairing older homes."}, {"type": "paragraph", "text": "Each store can adjust its selection to serve local customers."}, {"type": "heading", "text": "Why independent hardware stores matter"}, {"type": "paragraph", "text": "Independent hardware stores provide more than merchandise."}, {"type": "paragraph", "text": "They can support their communities in several ways."}, {"type": "bullet", "text": "Local jobs: Stores employ people nearby. Employees gain experience and useful skills."}, {"type": "bullet", "text": "Community support: Many stores support local schools, charities, and events."}, {"type": "bullet", "text": "Local knowledge: Employees learn about common projects in their area."}, {"type": "bullet", "text": "Customer relationships: Employees may recognize returning customers and remember their projects."}, {"type": "paragraph", "text": "These relationships can help build trust."}, {"type": "heading", "text": "Your role in the store"}, {"type": "paragraph", "text": "Every employee contributes to the business."}, {"type": "paragraph", "text": "You may stock shelves, operate a register, or assist customers."}, {"type": "paragraph", "text": "Each task matters."}, {"type": "paragraph", "text": "Organized shelves help customers find products. Accurate transactions help the store operate smoothly. Friendly service makes customers feel welcome."}, {"type": "paragraph", "text": "Your work also affects the store’s reputation."}, {"type": "paragraph", "text": "Customers notice how employees treat them. They notice clean aisles and organized merchandise."}, {"type": "paragraph", "text": "Positive experiences give customers a reason to return."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A coastal store receives frequent requests for storm supplies. Staff share the requests with the manager. The store considers adjusting its seasonal selection."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Notice recurring local requests. Share them with the team. Treat each customer with respect."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Do not promise that every item is stocked. Do not claim your store always has the lowest prices."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager about product selection, store policy, or local claims."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Independent hardware stores serve their communities through useful products, local knowledge, and personal service. Every employee contributes to that mission."}, {"type": "bullet", "text": "Notice recurring local requests. Share them with the team. Treat each customer with respect."}, {"type": "bullet", "text": "Ask a manager about product selection, store policy, or local claims."}, {"type": "heading", "text": "Practice question — unscored"}, {"type": "paragraph", "text": "Customers often request specialty fasteners for older homes. What is one advantage of an independent hardware store?"}, {"type": "bullet", "text": "A. The store must carry every type of fastener."}, {"type": "bullet", "text": "B. The store can adjust its product selection to meet local needs."}, {"type": "bullet", "text": "C. The store should only sell products found in national chains."}, {"type": "bullet", "text": "D. The store should ignore requests from local customers."}, {"type": "callout", "text": "Pause and choose an answer before reading the explanation. This practice does not use a quiz attempt or earn points."}, {"type": "heading", "text": "Practice answer and explanation"}, {"type": "paragraph", "text": "B. The store can adjust its product selection to meet local needs. Independent stores can select products based on the needs of their communities."}]}, {"id": "90133465-90fa-5db3-9568-0efa8312ed32", "position": 2, "title": "How a Hardware Store Works", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Your tasks affect customers and coworkers. Clear handoffs help the store run well."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Lesson introduction"}, {"type": "paragraph", "text": "A customer needs a replacement faucet cartridge."}, {"type": "paragraph", "text": "The shelf is empty. The inventory system shows three in stock."}, {"type": "paragraph", "text": "An employee checks another display. A coworker checks the receiving area."}, {"type": "paragraph", "text": "They find the part and help the customer."}, {"type": "paragraph", "text": "This is teamwork. Store jobs are connected."}, {"type": "heading", "text": "Common store responsibilities"}, {"type": "paragraph", "text": "Hardware stores have many daily tasks."}, {"type": "bullet", "text": "Customer assistance: Help shoppers find products and understand their options."}, {"type": "bullet", "text": "Checkout: Process purchases and returns accurately."}, {"type": "bullet", "text": "Receiving: Check deliveries and record merchandise."}, {"type": "bullet", "text": "Stocking: Put products in the correct locations."}, {"type": "bullet", "text": "Merchandising: Keep displays, signs, and shelves clear and organized."}, {"type": "bullet", "text": "Store services: Perform approved tasks such as key cutting or paint mixing."}, {"type": "bullet", "text": "Housekeeping: Keep work areas clean and safe."}, {"type": "paragraph", "text": "In a small store, one employee may perform several of these jobs."}, {"type": "heading", "text": "Your work affects other people"}, {"type": "paragraph", "text": "Imagine a shipment of drill bits arrives."}, {"type": "paragraph", "text": "The receiving employee checks the boxes. The products are then placed in the wrong area."}, {"type": "paragraph", "text": "Later, a sales associate cannot find them for a customer."}, {"type": "paragraph", "text": "The system shows the products in stock. The shelf is empty."}, {"type": "paragraph", "text": "One mistake can affect several people."}, {"type": "heading", "text": "Three habits that help"}, {"type": "bullet", "text": "Finish the task: Complete each step of your assignment."}, {"type": "bullet", "text": "Share information: Report missing, damaged, or misplaced products."}, {"type": "bullet", "text": "Think about the next person: Leave clear information for the coworker who follows you."}, {"type": "paragraph", "text": "Ask about the correct process when you are unsure."}, {"type": "paragraph", "text": "Do not change inventory records or move products without permission."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a faucet cartridge. The shelf is empty. The inventory system shows stock. An employee checks other approved locations and asks receiving for help."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Finish your task. Tell the next employee about unresolved issues. Verify product locations before promising availability."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Do not assume the system is correct. Do not abandon unfinished receiving work without notice."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor or inventory lead about discrepancies, returns, or receiving procedures."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Every store job is connected. Complete tasks carefully and share useful information with your team."}, {"type": "bullet", "text": "Finish your task. Tell the next employee about unresolved issues. Verify product locations before promising availability."}, {"type": "bullet", "text": "Ask a supervisor or inventory lead about discrepancies, returns, or receiving procedures."}, {"type": "heading", "text": "Practice question — unscored"}, {"type": "paragraph", "text": "A customer needs a faucet cartridge. The system shows three in stock, but the shelf is empty. What should you do?"}, {"type": "bullet", "text": "A. Tell the customer the inventory system is wrong."}, {"type": "bullet", "text": "B. Check other possible locations and ask the right coworker for help."}, {"type": "bullet", "text": "C. Tell the customer to return another day."}, {"type": "bullet", "text": "D. Assume the product is unavailable without checking."}, {"type": "callout", "text": "Pause and choose an answer before reading the explanation. This practice does not use a quiz attempt or earn points."}, {"type": "heading", "text": "Practice answer and explanation"}, {"type": "paragraph", "text": "B. Check other possible locations and ask the right coworker for help. An empty shelf does not always mean an item is unavailable. Check approved locations and verify availability before making a promise."}]}, {"id": "dac4734c-2ea9-5315-bbc3-cbf242670956", "position": 3, "title": "Being a Dependable Team Member", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Dependable work builds trust. Small actions can prevent larger problems."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Lesson introduction"}, {"type": "paragraph", "text": "Two employees finish stocking their assigned shelves."}, {"type": "paragraph", "text": "One leaves the aisle right away."}, {"type": "paragraph", "text": "The other notices several products in the wrong spots."}, {"type": "paragraph", "text": "That employee checks the labels and fixes the problem."}, {"type": "paragraph", "text": "Both finished the assigned work. One also helped the next shift."}, {"type": "heading", "text": "What dependability looks like"}, {"type": "paragraph", "text": "Dependability means people can count on you."}, {"type": "bullet", "text": "Reliability: Arrive ready for work and complete your assignments."}, {"type": "bullet", "text": "Accountability: Admit mistakes and help correct them."}, {"type": "bullet", "text": "Initiative: Notice problems and take appropriate action."}, {"type": "bullet", "text": "Respect: Treat customers and coworkers professionally."}, {"type": "bullet", "text": "Learning: Ask questions and accept feedback."}, {"type": "bullet", "text": "Communication: Tell the team about changes or problems."}, {"type": "heading", "text": "Take ownership"}, {"type": "paragraph", "text": "You are restocking screws. Several shelf labels do not match the packages."}, {"type": "paragraph", "text": "Customers may see the wrong price. The cashier may face a pricing dispute."}, {"type": "paragraph", "text": "Check the information. Then follow your store’s process for correcting labels."}, {"type": "paragraph", "text": "Ask a supervisor if you do not have permission to make changes."}, {"type": "paragraph", "text": "Ownership does not mean doing every job yourself."}, {"type": "paragraph", "text": "It means taking a problem seriously and helping it reach the right person."}, {"type": "heading", "text": "Learn from mistakes"}, {"type": "paragraph", "text": "You place fasteners in the wrong location."}, {"type": "paragraph", "text": "A coworker notices the mistake."}, {"type": "paragraph", "text": "Thank the coworker. Fix the problem. Ask how to prevent it next time."}, {"type": "paragraph", "text": "New employees will make mistakes."}, {"type": "paragraph", "text": "A dependable employee learns and improves."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "You find fasteners on the wrong shelf. You check the shelf labels. You correct the location if allowed. You report the issue if you cannot verify it."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Show up prepared. Own mistakes. Check before moving products. Follow through."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Do not hide mistakes. Do not move products based on guesses."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor about pricing, labels, or tasks outside your authority."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Dependability grows through daily actions. Be prepared, follow through, and take responsibility."}, {"type": "bullet", "text": "Show up prepared. Own mistakes. Check before moving products. Follow through."}, {"type": "bullet", "text": "Ask a supervisor about pricing, labels, or tasks outside your authority."}, {"type": "heading", "text": "Practice question — unscored"}, {"type": "paragraph", "text": "You notice products in the wrong locations. Your assigned work is almost finished. What should you do?"}, {"type": "bullet", "text": "A. Ignore the products. They were not part of your assignment."}, {"type": "bullet", "text": "B. Move them wherever you think they belong."}, {"type": "bullet", "text": "C. Verify the correct locations. Fix the problem if permitted, or tell the right coworker."}, {"type": "bullet", "text": "D. Wait for another employee to notice the problem."}, {"type": "callout", "text": "Pause and choose an answer before reading the explanation. This practice does not use a quiz attempt or earn points."}, {"type": "heading", "text": "Practice answer and explanation"}, {"type": "paragraph", "text": "C. Verify the correct locations. Fix the problem if permitted, or tell the right coworker. Dependability includes noticing problems and taking responsible action. Check information before making changes."}]}, {"id": "f552d5c1-4bef-5b0c-bf70-c37dcb164a74", "position": 4, "title": "Working Together When Things Get Busy", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Busy periods require teamwork. Clear priorities help protect customers and staff."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Lesson introduction"}, {"type": "paragraph", "text": "It is Saturday morning. The store is busy."}, {"type": "paragraph", "text": "A delivery truck arrives. The checkout line grows."}, {"type": "paragraph", "text": "A customer needs help loading concrete. Another customer needs help in plumbing."}, {"type": "paragraph", "text": "Several tasks need attention."}, {"type": "paragraph", "text": "The team must decide what comes first."}, {"type": "heading", "text": "Recognize priorities"}, {"type": "paragraph", "text": "Start by looking for immediate safety concerns."}, {"type": "paragraph", "text": "Acknowledge waiting customers. Ask a coworker for help as needed."}, {"type": "paragraph", "text": "Think about your current assignment. Can you pause it safely?"}, {"type": "paragraph", "text": "Tell the right person about changes to your work."}, {"type": "paragraph", "text": "Some tasks cannot be left without securing the work area."}, {"type": "paragraph", "text": "For example, never leave operating equipment or an unsecured load unattended."}, {"type": "heading", "text": "Communicate clearly"}, {"type": "paragraph", "text": "Clear requests help coworkers respond."}, {"type": "paragraph", "text": "Unclear: “Somebody needs to help up front.”"}, {"type": "paragraph", "text": "Clear: “The checkout line is growing. Can an available cashier help?”"}, {"type": "paragraph", "text": "State the problem. Say where help is needed."}, {"type": "paragraph", "text": "Explain any urgent details."}, {"type": "heading", "text": "Handle disagreements with respect"}, {"type": "paragraph", "text": "Busy shifts can feel stressful."}, {"type": "paragraph", "text": "Coworkers may disagree about priorities."}, {"type": "paragraph", "text": "Focus on the problem. Avoid blame."}, {"type": "paragraph", "text": "Listen to the other person. They may be handling a task you cannot see."}, {"type": "paragraph", "text": "Ask a supervisor for guidance when priorities conflict."}, {"type": "heading", "text": "Work as one team"}, {"type": "paragraph", "text": "You may need to change tasks during a busy shift."}, {"type": "paragraph", "text": "Help customers and coworkers without losing track of your assignment."}, {"type": "paragraph", "text": "Good teamwork uses clear communication and sound judgment."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "The register line grows during a delivery. A customer also needs help loading concrete. The team assigns safe loading assistance and coordinates checkout coverage."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Acknowledge customers. State what help is needed. Secure your work before switching tasks."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Do not leave equipment or a load unsecured. Do not silently abandon an assignment."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor to resolve competing priorities or safety concerns."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Busy stores need clear communication, smart priorities, and teamwork. Never sacrifice safety to work faster."}, {"type": "bullet", "text": "Acknowledge customers. State what help is needed. Secure your work before switching tasks."}, {"type": "bullet", "text": "Ask a supervisor to resolve competing priorities or safety concerns."}, {"type": "heading", "text": "Practice question — unscored"}, {"type": "paragraph", "text": "You are stocking shelves. A customer asks for help loading concrete. Your manager also needs the stocking finished. What should you do?"}, {"type": "bullet", "text": "A. Tell the customer you are too busy."}, {"type": "bullet", "text": "B. Arrange help for the customer and communicate any change to your assigned work."}, {"type": "bullet", "text": "C. Leave the stocking area without telling anyone."}, {"type": "bullet", "text": "D. Promise to finish both tasks without asking for help."}, {"type": "callout", "text": "Pause and choose an answer before reading the explanation. This practice does not use a quiz attempt or earn points."}, {"type": "heading", "text": "Practice answer and explanation"}, {"type": "paragraph", "text": "B. Arrange help for the customer and communicate any change to your assigned work. Help the customer and keep your team informed. Ask for support when priorities compete."}]}, {"id": "2b5bac8d-f7d3-592f-a5ae-134357958706", "position": 5, "title": "Making Your First Customer Interaction Count", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The first conversation sets the tone. Good questions lead to better help."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Lesson introduction"}, {"type": "paragraph", "text": "You are organizing merchandise."}, {"type": "paragraph", "text": "A customer approaches you."}, {"type": "paragraph", "text": "“I want to hang a shelf in my garage. I am not sure what I need.”"}, {"type": "paragraph", "text": "You recognize some products. You do not know which ones fit this project."}, {"type": "paragraph", "text": "Start by asking questions."}, {"type": "heading", "text": "Step 1 — Acknowledge"}, {"type": "paragraph", "text": "Greet the customer. Give them your attention."}, {"type": "paragraph", "text": "You might say, “Good morning! What can I help you find today?”"}, {"type": "paragraph", "text": "A friendly greeting makes customers feel welcome."}, {"type": "heading", "text": "Step 2 — Ask"}, {"type": "paragraph", "text": "Learn about the customer’s project."}, {"type": "bullet", "text": "“What are you working on?”"}, {"type": "bullet", "text": "“Where will you use the product?”"}, {"type": "bullet", "text": "“Are you replacing something?”"}, {"type": "bullet", "text": "“Do you have a picture or an old part?”"}, {"type": "paragraph", "text": "Listen to the answers."}, {"type": "paragraph", "text": "Do not recommend a product before you understand the project."}, {"type": "heading", "text": "Step 3 — Assist"}, {"type": "paragraph", "text": "Help the customer find suitable products or information."}, {"type": "paragraph", "text": "Show them where products are located."}, {"type": "paragraph", "text": "Ask a knowledgeable coworker for help when needed."}, {"type": "paragraph", "text": "Do not guess about safety or product suitability."}, {"type": "paragraph", "text": "Verify important details before making a recommendation."}, {"type": "heading", "text": "Step 4 — Close"}, {"type": "paragraph", "text": "Make sure the customer knows the next step."}, {"type": "paragraph", "text": "Ask whether they need anything else."}, {"type": "paragraph", "text": "You might say, “Is there anything else I can help you find?”"}, {"type": "paragraph", "text": "Thank the customer for visiting."}, {"type": "heading", "text": "Put the steps together"}, {"type": "paragraph", "text": "Return to the customer who wants to hang a shelf."}, {"type": "paragraph", "text": "Ask about the wall material."}, {"type": "paragraph", "text": "Ask how much weight the shelf will hold."}, {"type": "paragraph", "text": "Ask whether the customer has mounting instructions."}, {"type": "paragraph", "text": "These details help determine the correct hardware."}, {"type": "paragraph", "text": "Share the information with an experienced coworker as needed."}, {"type": "paragraph", "text": "Stay involved when possible. Each interaction is a chance to learn."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to mount a heavy garage shelf. You ask about wall material, expected load, and product instructions. You check the next step with an experienced coworker."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Acknowledge. Ask. Assist. Close. Verify technical details before recommending products."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Do not recommend hardware based on size alone. Do not guess about load ratings."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Consult manufacturer instructions, an experienced coworker, or a qualified professional for structural or safety questions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Follow four steps: Acknowledge, Ask, Assist, and Close."}, {"type": "bullet", "text": "Acknowledge. Ask. Assist. Close. Verify technical details before recommending products."}, {"type": "bullet", "text": "Consult manufacturer instructions, an experienced coworker, or a qualified professional for structural or safety questions."}, {"type": "heading", "text": "Practice question — unscored"}, {"type": "paragraph", "text": "A customer needs hardware for a heavy shelf. What should you do first?"}, {"type": "bullet", "text": "A. Recommend the largest wall anchors."}, {"type": "bullet", "text": "B. Ask about the wall material, shelf weight, and mounting instructions."}, {"type": "bullet", "text": "C. Send the customer to the hardware aisle to choose."}, {"type": "bullet", "text": "D. Choose the first product you see without asking questions."}, {"type": "callout", "text": "Pause and choose an answer before reading the explanation. This practice does not use a quiz attempt or earn points."}, {"type": "heading", "text": "Practice answer and explanation"}, {"type": "paragraph", "text": "B. Ask about the wall material, shelf weight, and mounting instructions. The project details help determine the correct hardware. Ask questions before recommending products."}]}], "questions": [{"id": "e2a5d6ec-1fd3-5be3-8649-d7f77caa02f1", "position": 1, "prompt": "A customer asks why they should shop at your independent hardware store. Which answer best describes the store’s value?", "options": ["We always have the lowest prices.", "We offer personal service and products that reflect local needs.", "Our products are always better than those sold elsewhere.", "Every customer wants the same products."], "correct_option": 1, "explanation": "Independent stores can build relationships and respond to local needs. Avoid promises you cannot verify."}, {"id": "a8dc2a6b-5470-51f2-8b46-42cf24aec621", "position": 2, "prompt": "You finish stocking a delivery. Several boxes were not checked against the receiving paperwork. What should you do?", "options": ["Leave them. Your shelves are finished.", "Put the boxes on any open shelf.", "Tell the right coworker and follow the receiving process.", "Ignore the boxes until the next delivery."], "correct_option": 2, "explanation": "Accurate receiving helps the team find products and keep correct records."}, {"id": "d7528b44-d532-5d5c-b0e9-17f41f2ad042", "position": 3, "prompt": "You put products in the wrong location. A coworker points out the mistake. What should you do?", "options": ["Acknowledge the mistake, fix it, and learn the correct location.", "Blame confusing labels.", "Ignore the comment.", "Hide the mistake and hope nobody notices."], "correct_option": 0, "explanation": "Accountability means owning mistakes and helping correct them."}, {"id": "9b77164a-f61f-59e9-b3e6-f475d743af0d", "position": 4, "prompt": "You are stocking shelves. A customer needs help. The cashier also asks for support. What should you do?", "options": ["Keep stocking until your manager tells you to stop.", "Acknowledge the customer and coordinate help with coworkers or a supervisor.", "Leave your assignment without telling anyone.", "Assume another employee will handle both requests."], "correct_option": 1, "explanation": "Good teamwork means recognizing priorities and communicating changes."}, {"id": "3c7ab965-5e90-52d6-b833-c84ea89addbb", "position": 5, "prompt": "Which sequence best describes a complete customer interaction?", "options": ["Recommend a product, ask about the project, then return to your task.", "Greet the customer, point to an aisle, then help someone else.", "Acknowledge the customer, ask about the project, assist with reliable information, and close by confirming the next step and thanking them.", "Wait for the customer to choose a product, then explain why it should work."], "correct_option": 2, "explanation": "Acknowledge, Ask, Assist, and Close covers the full interaction: welcome the customer, understand the project, help without guessing, and confirm the next step before thanking them."}]}$rf101data$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
end;
$rf101import$;
commit;
select slug,title,published,
 (select count(*) from public.training_lessons where course_id=c.id) as lessons,
 (select count(*) from public.training_questions where course_id=c.id) as quiz_questions
from public.training_courses c where id='4c7cbaa4-ceb0-5b42-ae9e-692576e98585';
